"import pandas as pd
from collections import Counter

df = pd.read_csv(r'D:\Anuj\Pearl-ASsignment\amazon-products.csv', dtype=str, keep_default_na=False)

deps = df[df['department'] != '']['department']
lower_to_orig = {}
for d in deps:
    low = d.strip().lower()
    if low not in lower_to_orig:
        lower_to_orig[low] = Counter()
    lower_to_orig[low][d.strip()] += 1

print("Department casing discrepancies:")
for low, counts in lower_to_orig.items():
    if len(counts) > 1:
        print(f"'{low}': {dict(counts)}")
"
